class Solution:
    def maximumUniqueSubarray(self, nums: list[int]) -> int:
        n = len(nums)
        ans = 0
        for i in range(n):
            for j in range(i, n):
                seen = set()
                total = 0
                ok = True
                for p in range(i, j + 1):
                    if nums[p] in seen:
                        ok = False
                    seen.add(nums[p])
                    total += nums[p]
                if ok:
                    ans = max(ans, total)
        return ans

