class Solution:
    def maximumUniqueSubarray(self, nums: list[int]) -> int:
        n = len(nums)
        ans = 0
        for i in range(n):
            seen = set()
            total = 0
            for j in range(i, n):
                if nums[j] in seen:
                    break
                seen.add(nums[j])
                total += nums[j]
                ans = max(ans, total)
        return ans

